function useServer(ctx) {
  before(async () => {
    ctx.dir = await makeTempDir();
    ctx.srv = await startServer({ cwd: ctx.dir, env: { DATA_FILE: join(ctx.dir, 'data.json') } });
    ctx.port = ctx.srv.port;
